abel{color:#3c568e;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.eyebrow{display:inline-flex;gap:8px;padding:7px 11px;border-radius:99px;background:#e6eeff}.eyebrow:before{content:'';width:7px;height:7px;border-radius:50%;background:var(--coral)}h1,h2,h3{font-family:Manrope,sans-serif}h1{margin:18px 0 20px;font-size:clamp(45px,5vw,70px);line-height:1.03;letter-spacing:-3.5px}.copy{max-width:520px;margin:0;color:var(--muted);font-size:18px;line-height:1.62}.hero-actions{display:flex;gap:17px;align-items:center;margin:30px 0 18px}.text{color:#374d80;font-size:14px;font-weight:700}.proof{display:flex;gap:16px;flex-wrap:wrap;color:#73819a;font-size:12px}.proof span:before{content:'✓';display:inline-grid;place-items:center;width:15px;height:15px;margin-right:6px;border-radius:50%;background:#dff3b5;color:#426d1f;font-weight:bold}.frame{padding:10px;border-radius:18px;background:linear-gradient(145deg,#2a3b66,#101a35);box-shadow:0 30px 65px rgba(32,51,96,.24);transform:perspective(1400px) rotateY(-4deg)}.app{overflow:hidden;min-height:390px;border-radius:11px;background:#f7f9fd}.top{display:flex;align-items:center;height:37px;padding:0 14px;background:#fff;border-bottom:1px solid #e6eaf2;color:#8390a7;font-size:9px}.dot{width:6px;height:6px;margin-right:3px;border-radius:50%;background:#d7deea}.appname{margin-left:10px;color:#344363;font-weight:800}.date{margin-left:auto}.appmain{display:grid;grid-template-columns:105px 1fr}.side{padding:13px 9px;background:#fff;border-right:1px solid #e6eaf2}.side b{display:block;padding:6px 7px;color:#7d899e;font-size:8px;text-transform:uppercase}.navitem{margin:3px 0;padding:7px;border-radius:5px;color:#718099;font-size:9px}.navitem.active{background:#edf2ff;color:#26375d;font-weight:800}.work{padding:17px 18px}.workhead{display:flex;justify-content:space-between;align-items:center}.work h3{margin:0;font-size:14px}.add{padding:7px 9px;border-radius:5px;background:var(--coral);color:#fff;font-size:9px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:15px 0}.metric,.panel{padding:10px;border:1px solid #e7ebf3;border-radius:7px;background:#fff}.metric label{display:block;color:#8490a6;font-size:8px}.metric b{display:block;margin:4px 0;color:#1e2b4b;font:800 17px Manrope}.metric small{color:#41915c;font-size:8px}.panels{display:grid;grid-template-columns:1.12fr .88fr;gap:10px}.ptitle{display:flex;justify-content:space-between;color:#52617b;font-size:9px;font-weight:800}.bars{display:flex;align-items:end;gap:7px;height:92px;padding:9px 0 12px}.bar{flex:1;border-radius:3px 3px 0 0;background:#c7d6ff}.bar:nth-child(2){height:55%!important}.bar:nth-child(3){background:#c9e980;height:38%!important}.bar:nth-child(4){background:#f3a18f;height:22%!important}.lead{padding:7px 0;border-top:1px solid #eef1f6;color:#354364;font-size:8px}.lead:first-of-type{border:0}.lead:before{content:'';display:inline-block;width:7px;height:7px;margin-right:6px;border-radius:50%;background:var(--coral)}.strip{padding:26px 0;border-bottom:1px solid var(--line)}.strip .wrap{display:flex;align-items:center;justify-content:space-between;gap:22px}.strip p{margin:0;color:#7d899e;font-size:12px}.tags{display:flex;gap:28px;color:#50607c;font:700 12px Manrope;text-transform:uppercase}.platform{padding:100px 0}.label{color:var(--coral)}h2{max-width:720px;margin:13px 0 16px;font-size:clamp(32px,3.8vw,50px);line-height:1.1;letter-spacing:-2px}.sectioncopy{max-width:560px;color:var(--muted);line-height:1.65}.features,.flowgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:17px;margin-top:40px}.feature{padding:27px;border:1px solid var(--line);border-radius:13px;background:#fff}.feature:first-child{background:var(--ink);color:#fff}.feature b{display:block;color:var(--coral);font:800 12px Manrope}.feature:first-child b{color:var(--lime)}.feature h3{margin:24px 0 10px;font-size:20px}.feature p{margin:0;color:var(--muted);font-size:14px;line-height:1.55}.feature:first-child p{color:#c4cfe6}.flow{padding:82px 0;background:#f5f7fc}.flowcard{padding:25px;border:1px solid #e0e6f1;border-radius:11px;background:#fff}.no{color:#a5b2ca;font:800 12px Manrope}.flowcard h3{margin:26px 0 10px;font-size:20px}.flowcard p{margin:0;color:var(--muted);font-size:14px;line-height:1.55}.cta{padding:98px 0;background:linear-gradient(135deg,#162344,#253867);color:#fff;text-align:center}.cta h2{margin:13px auto;font-size:46px}.cta p{max-width:560px;margin:0 auto 28px;color:#c4d0e8;line-height:1.65}.cta .btn{background:var(--coral)}footer{padding:27px 0;background:#101a35;color:#9faec9;font-size:12px}footer .wrap{display:flex;justify-content:space-between;gap:15px}@media(max-width:850px){.links{display:none}.hero{padding:60px 0}.grid{grid-template-columns:1fr;gap:38px}.frame{max-width:650px;transform:none}.features,.flowgrid{grid-template-columns:1fr}.strip .wrap{display:block}.tags{margin-top:14px;flex-wrap:wrap}}@media(max-width:520px){.wrap{width:min(100% - 28px,1180px)}.actions a:first-child{display:none}h1{font-size:45px;letter-spacing:-2.4px}.hero-actions{flex-direction:column;align-items:stretch}.appmain{grid-template-columns:72px 1fr}.navitem{font-size:0}.work{padding:12px}.metrics{gap:5px}.metric{padding:7px}.metric b{font-size:14px}.panels{grid-template-columns:1fr}.panels .panel:last-child{display:none}.cta{padding:72px 0}.cta h2{font-size:36px}footer .wrap{display:block}footer span+span{display:block;margin-top:7px}}</style></head><body><div class="announce">A focused CRM for teams that turn property conversations into revenue.<a href="{{ route('company-registration.create') }}">Create your workspace →</a></div><header class="wrap nav"><a class="brand" href="{{ route('home') }}"><span class="mark">E</span>ElyLeads</a><nav class="links"><a href="#platform">Platform</a><a href="#workflow">How it works</a></nav><div class="actions"><a href="{{ route('login') }}">Sign in</a><a class="btn" href="{{ route('company-registration.create') }}">Start free</a></div></header><main><section class="hero"><div class="wrap grid"><div><span class="eyebrow">Built for real estate teams</span><h1>Your next deal is already in your pipeline.</h1><p class="copy">ElyLeads gives every enquiry a responsible representative, every follow-up a next step, and every manager a clear view of the deals that need attention.</p><div class="hero-actions"><a class="btn" href="{{ route('company-registration.create') }}">Create your workspace</a><a class="text" href="#workflow">See how ElyLeads works →</a></div><div class="proof"><span>Built for brokerages and sales teams</span><span>One secure workspace per company</span></div></div><div class="frame"><div class="app"><div class="top"><i class="dot"></i><i class="dot"></i><i class="dot"></i><b class="appname">ELYLEADS / SALES</b><span class="date">Tuesday, 24 Sep</span></div><div class="appmain"><aside class="side"><b>Workspace</b><div class="navitem active">Dashboard</div><div class="navitem">Leads</div><div class="navitem">Follow-ups</div><div class="navitem">Team</div><b>Manage</b><div class="navitem">Reports</div></aside><div class="work"><div class="workhead"><h3>Sales overview</h3><span class="add">+ Add lead</span></div><div class="metrics"><div class="metric"><label>New enquiries</label><b>38</b><small>↑ 12% this week</small></div><div class="metric"><label>Follow-ups due</label><b>14</b><small>6 due today</small></div><div class="metric"><label>Won this month</label><b>₹2.4Cr</b><small>↑ 18% this month</small></div></div><div class="panels"><div class="panel"><div class="ptitle"><span>Pipeline health</span><span>Last 30 days</span></div><div class="bars"><i class="bar" style="height:70%"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i></div></div><div class="panel"><div class="ptitle"><span>Needs attention</span><span>View all</span></div><div class="lead">Ananya Kapoor</div><div class="lead">Rohan Mehta</div><div class="lead">Vikram Shah</div></div></div></div></div></div></div></div></div></section><section class="strip"><div class="wrap"><p>One platform for the revenue work real estate teams do every day.</p><div class="tags"><span>Leads</span><span>Site visits</span><span>Follow-ups</span><span>Team accountability</span></div></div></section><section id="platform" class="platform wrap"><span class="label">The ElyLeads platform</span><h2>The operating rhythm that turns interest into intent.</h2><p class="sectioncopy">A real estate CRM should make your next action obvious—not give your team another system to manage.</p><div class="features"><article class="feature"><b>01 / Capture</b><h3>Every enquiry arrives with context.</h3><p>Bring portal and campaign leads into one workflow, with the detail your team needs to start the right conversation.</p></article><article class="feature"><b>02 / Coordinate</b><h3>Every lead has a clear assigned representative.</h3><p>Assign, follow up, and schedule visits without losing track of responsibility or timing.</p></article><article class="feature"><b>03 / Convert</b><h3>Every manager sees the real pipeline.</h3><p>Move from activity to insight with a clear view of progress, outcomes, and team momentum.</p></article></div></section><section id="workflow" class="flow"><div class="wrap"><span class="label">A better way to work leads</span><h2>A simple flow. A serious sales engine.</h2><div class="flowgrid"><article class="flowcard"><span class="no">SOURCE</span><h3>Lead sources, connected</h3><p>Keep portal enquiries and sales activity in a shared company workspace.</p></article><article class="flowcard"><span class="no">ACTION</span><h3>Follow-ups that happen</h3><p>Surface the conversations, visits, and actions that need attention today.</p></article><article class="flowcard"><span class="no">VISIBILITY</span><h3>Growth you can see</h3><p>Give managers a dependable picture of conversion and team progress.</p></article></div></div></section><section class="cta"><div class="wrap"><span class="label" style="color:var(--lime)">Set up in minutes</span><h2>Give your team a workspace built for the way property deals move.</h2><p>Create a secure company workspace, then invite your sales team when you are ready.</p><a class="btn" href="{{ route('company-registration.create') }}">Create your workspace</a></div></section></main><footer><div class="wrap"><span>© {{ now()->year }} ElyLeads</span><span>The real estate operating system for teams that follow through.</span></div></footer></body></html>
